namespace sv_32f1ed01b2d04172858e79d70a7e906a.Services;

public record Channel(int Id, string Name, string Description, int UnreadCount);
public record Message(int Id, int ChannelId, string Author, string Content, DateTime SentAt, int? ReplyToId, List<Reaction> Reactions);
public record Reaction(string Emoji, List<string> Users);
public record ThreadSummary(int RootMessageId, int ReplyCount, DateTime LastReplyAt);

public interface IChatService
{
    Task<List<Channel>> GetChannelsAsync();
    Task<List<Message>> GetMessagesAsync(int channelId, int skip, int take);
    Task<Message> SendMessageAsync(int channelId, string content, int? replyToId);
    Task<List<Message>> GetThreadAsync(int rootMessageId);
    Task AddReactionAsync(int messageId, string emoji);
    Task MarkChannelReadAsync(int channelId);
}

namespace sv_32f1ed01b2d04172858e79d70a7e906a.Services;

public class StubChatService : IChatService
{
    private readonly List<Channel> _channels;
    private readonly List<Message> _messages;
    private int _nextMessageId = 100;

    public StubChatService()
    {
        _channels =
        [
            new(1, "general", "General discussion for the team", 3),
            new(2, "engineering", "Engineering updates and discussions", 0),
            new(3, "design", "Design reviews and feedback", 1),
            new(4, "random", "Off-topic conversations", 5),
            new(5, "announcements", "Important team announcements", 0),
        ];

        var now = DateTime.UtcNow;
        _messages =
        [
            new(1, 1, "Alice", "Hey team! Welcome to the new chat app 🎉", now.AddHours(-4), null, [new("🎉", ["Bob", "Carol"]), new("👍", ["Dave"])]),
            new(2, 1, "Bob", "Looks great! Really like the new design.", now.AddHours(-3.5), null, [new("❤️", ["Alice"])]),
            new(3, 1, "Carol", "Thanks for setting this up. Quick question about the project timeline?", now.AddHours(-3), null, []),
            new(4, 1, "Alice", "Sure! Let's discuss in a thread.", now.AddHours(-2.8), 3, []),
            new(5, 1, "Dave", "The deadline is next Friday. We should be on track.", now.AddHours(-2.5), 3, []),
            new(6, 1, "Carol", "Perfect, thanks for confirming!", now.AddHours(-2.3), 3, [new("👍", ["Alice", "Dave"])]),
            new(7, 1, "Dave", "Has anyone reviewed the latest PR?", now.AddMinutes(-45), null, []),
            new(8, 1, "Bob", "I'll take a look this afternoon.", now.AddMinutes(-30), null, []),
            new(9, 1, "Alice", "Don't forget our standup at 3pm!", now.AddMinutes(-10), null, [new("👍", ["Bob", "Carol", "Dave"])]),
            new(10, 1, "Eve", "Just joined the channel. Hi everyone!", now.AddMinutes(-2), null, [new("👋", ["Alice", "Bob"])]),

            new(20, 2, "Dave", "Deployed v2.1.0 to staging.", now.AddHours(-6), null, [new("🎉", ["Alice", "Bob", "Carol"])]),
            new(21, 2, "Alice", "CI pipeline is green. All 247 tests passing.", now.AddHours(-5), null, [new("👍", ["Dave"])]),
            new(22, 2, "Bob", "Found a minor regression in the search module.", now.AddHours(-1), null, []),
            new(23, 2, "Dave", "Can you file a bug? I'll look into it.", now.AddMinutes(-50), 22, []),
            new(24, 2, "Bob", "Done — issue #342.", now.AddMinutes(-45), 22, [new("👍", ["Dave"])]),

            new(30, 3, "Carol", "New mockups for the dashboard are ready for review.", now.AddHours(-2), null, [new("👀", ["Alice", "Bob"])]),
            new(31, 3, "Alice", "Love the color scheme! One suggestion on the nav layout.", now.AddHours(-1.5), null, []),

            new(40, 4, "Bob", "Anyone up for lunch at the new place downtown?", now.AddHours(-3), null, [new("🎉", ["Carol"]), new("👍", ["Dave", "Eve"])]),
            new(41, 4, "Eve", "Count me in!", now.AddHours(-2.8), null, []),
            new(42, 4, "Carol", "Same! What time?", now.AddHours(-2.5), null, []),
            new(43, 4, "Bob", "12:30 sound good?", now.AddHours(-2.3), null, [new("👍", ["Carol", "Eve"])]),

            new(50, 5, "Alice", "Team offsite is confirmed for August 15-16.", now.AddDays(-1), null, [new("🎉", ["Bob", "Carol", "Dave", "Eve"])]),
            new(51, 5, "Alice", "Please fill out the travel form by end of this week.", now.AddDays(-1).AddMinutes(5), null, []),
        ];
    }

    public Task<List<Channel>> GetChannelsAsync()
        => Task.FromResult(_channels.Select(c => c with { }).ToList());

    public Task<List<Message>> GetMessagesAsync(int channelId, int skip, int take)
    {
        var msgs = _messages
            .Where(m => m.ChannelId == channelId && m.ReplyToId == null)
            .OrderByDescending(m => m.SentAt)
            .Skip(skip)
            .Take(take)
            .OrderBy(m => m.SentAt)
            .ToList();
        return Task.FromResult(msgs);
    }

    public Task<Message> SendMessageAsync(int channelId, string content, int? replyToId)
    {
        var id = Interlocked.Increment(ref _nextMessageId);
        var msg = new Message(id, channelId, "You", content, DateTime.UtcNow, replyToId, []);
        _messages.Add(msg);
        return Task.FromResult(msg);
    }

    public Task<List<Message>> GetThreadAsync(int rootMessageId)
    {
        var root = _messages.FirstOrDefault(m => m.Id == rootMessageId);
        if (root == null) return Task.FromResult(new List<Message>());

        var replies = _messages
            .Where(m => m.ReplyToId == rootMessageId)
            .OrderBy(m => m.SentAt)
            .ToList();

        var result = new List<Message> { root };
        result.AddRange(replies);
        return Task.FromResult(result);
    }

    public Task AddReactionAsync(int messageId, string emoji)
    {
        var msg = _messages.FirstOrDefault(m => m.Id == messageId);
        if (msg != null)
        {
            var existing = msg.Reactions.FirstOrDefault(r => r.Emoji == emoji);
            if (existing != null)
            {
                if (!existing.Users.Contains("You"))
                    existing.Users.Add("You");
            }
            else
            {
                msg.Reactions.Add(new Reaction(emoji, ["You"]));
            }
        }
        return Task.CompletedTask;
    }

    public Task MarkChannelReadAsync(int channelId)
    {
        var idx = _channels.FindIndex(c => c.Id == channelId);
        if (idx >= 0)
            _channels[idx] = _channels[idx] with { UnreadCount = 0 };
        return Task.CompletedTask;
    }

    public int GetReplyCount(int rootMessageId)
        => _messages.Count(m => m.ReplyToId == rootMessageId);

    public DateTime? GetLastReplyAt(int rootMessageId)
        => _messages.Where(m => m.ReplyToId == rootMessageId)
            .OrderByDescending(m => m.SentAt)
            .Select(m => (DateTime?)m.SentAt)
            .FirstOrDefault();
}

