arguments.file_text:
@using sv_32f1ed01b2d04172858e79d70a7e906a.Services

<div class="message-list" @onscroll="HandleScroll">
    @if (IsLoading)
    {
        <div class="loading-indicator">Loading older messages...</div>
    }
    else if (HasMore)
    {
        <div class="load-more">
            <button class="load-more-btn" @onclick="LoadMore">⬆ Load older messages</button>
        </div>
    }

    @foreach (var message in Messages)
    {
        <MessageItem Message="message"
                     ReplyCount="GetReplyCount(message.Id)"
                     OnOpenThread="OnOpenThread"
                     OnReact="OnReact" />
    }
</div>

@code {
    [Parameter, EditorRequired] public List<Message> Messages { get; set; } = [];
    [Parameter] public Dictionary<int, int> ReplyCounts { get; set; } = [];
    [Parameter] public bool HasMore { get; set; }
    [Parameter] public bool IsLoading { get; set; }
    [Parameter] public EventCallback OnLoadMore { get; set; }
    [Parameter] public EventCallback<int> OnOpenThread { get; set; }
    [Parameter] public EventCallback<(int MessageId, string Emoji)> OnReact { get; set; }

    private int GetReplyCount(int messageId)
        => ReplyCounts.GetValueOrDefault(messageId, 0);

    private async Task HandleScroll()
    {
        // Scroll-to-top detection would need JS interop for precise detection.
        // The "Load older messages" button above provides the same functionality.
    }

    private async Task LoadMore() => await OnLoadMore.InvokeAsync();
}

.message-list {
    flex: 1;
    overflow-y: auto;
    padding: 8px 0;
    display: flex;
    flex-direction: column;
}

.loading-indicator {
    text-align: center;
    padding: 12px;
    color: #999;
    font-size: 0.85rem;
}

.load-more {
    text-align: center;
    padding: 8px;
}

.load-more-btn {
    background: none;
    border: 1px solid #ddd;
    border-radius: 6px;
    padding: 6px 16px;
    font-size: 0.82rem;
    color: #5865f2;
    cursor: pointer;
    transition: all 0.15s;
}

.load-more-btn:hover {
    background-color: #f0f0ff;
    border-color: #5865f2;
}

@using sv_32f1ed01b2d04172858e79d70a7e906a.Services

<div class="message-area">
    @if (Channel != null)
    {
        <div class="area-header">
            <h2># @Channel.Name</h2>
            <span class="area-description">@Channel.Description</span>
        </div>

        <MessageList Messages="Messages"
                     ReplyCounts="ReplyCounts"
                     HasMore="HasMore"
                     IsLoading="IsLoadingMore"
                     OnLoadMore="OnLoadMore"
                     OnOpenThread="OnOpenThread"
                     OnReact="OnReact" />

        <MessageInput Placeholder="@($"Message #{Channel.Name}")"
                      ButtonLabel="Send"
                      OnSend="OnSendMessage" />
    }
    else
    {
        <div class="empty-state">
            <p>Select a channel to start chatting</p>
        </div>
    }
</div>

@code {
    [Parameter] public Channel? Channel { get; set; }
    [Parameter] public List<Message> Messages { get; set; } = [];
    [Parameter] public Dictionary<int, int> ReplyCounts { get; set; } = [];
    [Parameter] public bool HasMore { get; set; }
    [Parameter] public bool IsLoadingMore { get; set; }
    [Parameter] public EventCallback OnLoadMore { get; set; }
    [Parameter] public EventCallback<int> OnOpenThread { get; set; }
    [Parameter] public EventCallback<(int MessageId, string Emoji)> OnReact { get; set; }
    [Parameter] public EventCallback<string> OnSendMessage { get; set; }
}

.message-area {
    flex: 1;
    display: flex;
    flex-direction: column;
    height: 100%;
    background: #fff;
    overflow: hidden;
}

.area-header {
    padding: 14px 20px;
    border-bottom: 1px solid #e0e0e0;
    background: #fff;
    flex-shrink: 0;
}

.area-header h2 {
    margin: 0;
    font-size: 1.15rem;
    font-weight: 700;
    color: #2c2f33;
}

.area-description {
    font-size: 0.82rem;
    color: #888;
    margin-top: 2px;
    display: block;
}

.empty-state {
    flex: 1;
    display: flex;
    align-items: center;
    justify-content: center;
    color: #999;
    font-size: 1.1rem;
}

@using sv_32f1ed01b2d04172858e79d70a7e906a.Services

<div class="thread-panel">
    <div class="thread-header">
        <h3>Thread</h3>
        <button class="close-btn" @onclick="OnClose">✕</button>
    </div>

    @if (RootMessage != null)
    {
        <div class="thread-root-quote">
            <div class="root-author">@RootMessage.Author</div>
            <div class="root-content">@RootMessage.Content</div>
        </div>
    }

    <div class="thread-replies">
        @foreach (var msg in Replies)
        {
            <MessageItem Message="msg"
                         ReplyCount="0"
                         OnOpenThread="EventCallback<int>.Empty"
                         OnReact="OnReact" />
        }
    </div>

    <MessageInput Placeholder="Reply..."
                  ButtonLabel="Reply"
                  OnSend="OnReply" />
</div>

