@using sv_32f1ed01b2d04172858e79d70a7e906a.Services

<div class="message-list" @onscroll="HandleScroll">
    @if (IsLoading)
    {
        <div class="loading-indicator">Loading older messages...</div>
    }
    else if (HasMore)
    {
        <div class="load-more">
            <button class="load-more-btn" @onclick="LoadMore">⬆ Load older messages</button>
        </div>
    }

    @foreach (var message in Messages)
    {
        <MessageItem Message="message"
                     ReplyCount="GetReplyCount(message.Id)"
                     OnOpenThread="OnOpenThread"
                     OnReact="OnReact" />
    }
</div>

@code {
    [Parameter, EditorRequired] public List<Message> Messages { get; set; } = [];
    [Parameter] public Dictionary<int, int> ReplyCounts { get; set; } = [];
    [Parameter] public bool HasMore { get; set; }
    [Parameter] public bool IsLoading { get; set; }
    [Parameter] public EventCallback OnLoadMore { get; set; }
    [Parameter] public EventCallback<int> OnOpenThread { get; set; }
    [Parameter] public EventCallback<(int MessageId, string Emoji)> OnReact { get; set; }

    private int GetReplyCount(int messageId)
        => ReplyCounts.GetValueOrDefault(messageId, 0);

    private async Task HandleScroll()
    {
        // Scroll-to-top detection would need JS interop for precise detection.
        // The "Load older messages" button above provides the same functionality.
    }

    private async Task LoadMore() => await OnLoadMore.InvokeAsync();
}

