<div class="thread-panel">
    <div class="thread-header">
        <h3>Thread</h3>
        <button class="close-btn" @onclick="OnClose">✕</button>
    </div>

    @if (RootMessage != null)
    {
        <div class="thread-root-quote">
            <div class="root-author">@RootMessage.Author</div>
            <div class="root-content">@RootMessage.Content</div>
        </div>
    }

    <div class="thread-replies">
        @foreach (var msg in Replies)
        {
            <MessageItem Message="msg"
                         ReplyCount="0"
                         OnOpenThread="EventCallback<int>.Empty"
                         OnReact="OnReact" />
        }
    </div>

    <MessageInput Placeholder="Reply..."
                  ButtonLabel="Reply"
                  OnSend="OnReply" />
</div>

@code {
    [Parameter] public Message? RootMessage { get; set; }
    [Parameter] public List<Message> Replies { get; set; } = [];
    [Parameter] public EventCallback OnClose { get; set; }
    [Parameter] public EventCallback<string> OnReply { get; set; }
    [Parameter] public EventCallback<(int MessageId, string Emoji)> OnReact { get; set; }

    private static readonly EventCallback<int> _emptyCallback = EventCallback<int>.Empty;
}

.thread-panel {
    width: 100%;
    height: 100%;
    display: flex;
    flex-direction: column;
    background: #fafafa;
    border-left: 1px solid #e0e0e0;
    overflow: hidden;
}

.thread-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 14px 16px;
    border-bottom: 1px solid #e0e0e0;
    background: #fff;
    flex-shrink: 0;
}

.thread-header h3 {
    margin: 0;
    font-size: 1.05rem;
    font-weight: 700;
    color: #2c2f33;
}

.close-btn {
