@page "/chat"
@layout sv_32f1ed01b2d04172858e79d70a7e906a.Components.Layout.ChatLayout
@rendermode InteractiveServer
@using sv_32f1ed01b2d04172858e79d70a7e906a.Services
@inject IChatService ChatService

<PageTitle>Chat</PageTitle>

<div class="chat-container">
    <div class="sidebar-panel">
        <ChannelSidebar Channels="_channels"
                        ActiveChannelId="_selectedChannelId"
                        OnChannelSelected="SelectChannel" />
    </div>

    <div class="main-panel">
        <MessageArea Channel="_selectedChannel"
                     Messages="_messages"
                     ReplyCounts="_replyCounts"
                     HasMore="_hasMore"
                     IsLoadingMore="_isLoadingMore"
                     OnLoadMore="LoadOlderMessages"
                     OnOpenThread="OpenThread"
                     OnReact="HandleReaction"
                     OnSendMessage="SendMessage" />
    </div>

    @if (_isThreadOpen && _threadRootMessage != null)
    {
        <div class="thread-panel-container">
            <ThreadPanel RootMessage="_threadRootMessage"
                         Replies="_threadReplies"
                         OnClose="CloseThread"
                         OnReply="SendThreadReply"
                         OnReact="HandleReaction" />
        </div>
    }
</div>

@code {
    private List<Channel> _channels = [];
    private List<Message> _messages = [];
    private Dictionary<int, int> _replyCounts = [];
    private Channel? _selectedChannel;
    private int _selectedChannelId;

    private bool _isThreadOpen;
    private Message? _threadRootMessage;
    private List<Message> _threadReplies = [];

    private bool _hasMore;
    private bool _isLoadingMore;
    private const int PageSize = 20;

    protected override async Task OnInitializedAsync()
    {
        _channels = await ChatService.GetChannelsAsync();
        if (_channels.Count > 0)
        {
            await SelectChannel(_channels[0].Id);
        }
    }

    private async Task SelectChannel(int channelId)
    {
        _selectedChannelId = channelId;
        _selectedChannel = _channels.FirstOrDefault(c => c.Id == channelId);
        _isThreadOpen = false;
        _threadRootMessage = null;
        _threadReplies = [];

        _messages = await ChatService.GetMessagesAsync(channelId, 0, PageSize);
        _hasMore = _messages.Count >= PageSize;
        await UpdateReplyCounts();
        await ChatService.MarkChannelReadAsync(channelId);

        // Refresh channel list to update unread counts
        _channels = await ChatService.GetChannelsAsync();
    }

    private async Task LoadOlderMessages()
    {
        if (_isLoadingMore || !_hasMore) return;
        _isLoadingMore = true;

        var older = await ChatService.GetMessagesAsync(_selectedChannelId, _messages.Count, PageSize);
        _hasMore = older.Count >= PageSize;

        // Prepend older messages
        _messages.InsertRange(0, older);
        await UpdateReplyCounts();
        _isLoadingMore = false;
    }

    private async Task SendMessage(string content)
    {
        var msg = await ChatService.SendMessageAsync(_selectedChannelId, content, null);
        _messages.Add(msg);
    }

    private async Task OpenThread(int messageId)
    {
        var thread = await ChatService.GetThreadAsync(messageId);
        if (thread.Count > 0)
        {
            _threadRootMessage = thread[0];
            _threadReplies = thread.Skip(1).ToList();
            _isThreadOpen = true;
        }
    }

    private void CloseThread()
    {
        _isThreadOpen = false;
        _threadRootMessage = null;
        _threadReplies = [];
    }

    private async Task SendThreadReply(string content)
    {
        if (_threadRootMessage == null) return;
        var reply = await ChatService.SendMessageAsync(
            _selectedChannelId, content, _threadRootMessage.Id);
        _threadReplies.Add(reply);
        await UpdateReplyCounts();
    }

    private async Task HandleReaction((int MessageId, string Emoji) args)
    {
        await ChatService.AddReactionAsync(args.MessageId, args.Emoji);
        // Refresh messages to reflect new reaction
        _messages = await ChatService.GetMessagesAsync(_selectedChannelId, 0, Math.Max(_messages.Count, PageSize));
        if (_isThreadOpen && _threadRootMessage != null)
        {
            var thread = await ChatService.GetThreadAsync(_threadRootMessage.Id);
            if (thread.Count > 0)
            {
                _threadRootMessage = thread[0];
                _threadReplies = thread.Skip(1).ToList();
            }
        }
    }

    private async Task UpdateReplyCounts()
    {
        // Build reply counts from message data
        _replyCounts = [];
        foreach (var msg in _messages)
        {
            var thread = await ChatService.GetThreadAsync(msg.Id);
            var replyCount = thread.Count - 1; // Exclude root message
            if (replyCount > 0)
                _replyCounts[msg.Id] = replyCount;
        }
    }
}

.chat-container {
    display: flex;
    height: 100vh;
    width: 100vw;
    overflow: hidden;
}

.sidebar-panel {
    width: 20%;
    min-width: 200px;
    max-width: 280px;
    flex-shrink: 0;
    height: 100%;
}

.main-panel {
    flex: 1;
    height: 100%;
    min-width: 0;
}

.thread-panel-container {
    width: 25%;
    min-width: 280px;
    max-width: 400px;
    flex-shrink: 0;
    height: 100%;
}

